import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

masked_cumsum_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

template<typename scalar_t>
__global__ void masked_cumsum_kernel(
    const scalar_t* x,
    const bool* mask,
    scalar_t* out,
    int num_sequences,
    int seq_length
) {
    const int batch = blockIdx.x * blockDim.x + threadIdx.x;
    const int stride = blockDim.x * gridDim.x;

    for (int b = batch; b < num_sequences; b += stride) {
        scalar_t sum = 0;
        for (int i = 0; i < seq_length; ++i) {
            const int idx = b * seq_length + i;
            sum += x[idx] * (mask[idx] ? 1 : 0);
            out[idx] = sum;
        }
    }
}

torch::Tensor masked_cumsum_cuda(torch::Tensor x, torch::Tensor mask, int dim) {
    auto sizes = x.sizes();
    auto out = torch::zeros_like(x);

    int num_sequences = x.numel() / sizes[dim];
    int seq_length = sizes[dim];

    const int block_size = 256;
    const int grid_size = (num_sequences + block_size - 1) / block_size;

    AT_DISPATCH_FLOATING_TYPES(x.scalar_type(), "masked_cumsum", [&] {
        masked_cumsum_kernel<scalar_t><<<grid_size, block_size>>>(
            x.data_ptr<scalar_t>(),
            mask.data_ptr<bool>(),
            out.data_ptr<scalar_t>(),
            num_sequences,
            seq_length
        );
    });

    return out;
}
"""

masked_cumsum_cpp_source = "torch::Tensor masked_cumsum_cuda(torch::Tensor x, torch::Tensor mask, int dim);"

masked_cumsum = load_inline(
    name='masked_cumsum',
    cpp_sources=masked_cumsum_cpp_source,
    cuda_sources=masked_cumsum_source,
    functions=['masked_cumsum_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x, mask):
        return masked_cumsum.masked_cumsum_cuda(x, mask, self.dim)
